      "support_status": "SUFFICIENT",
      "rationale": "P021 explicitly states that complete histories do not prove correct identity linkage."
    }
  },
  "signal_basis": {
    "component_id": "C043.signal_basis",
    "value": "Account and schedule identifiers are used to link events and check schedule lineage; inspection finds an internally consistent history connecting participants, preparation, draft versions and publication, with reported offline activity distinguished from logged events.",
    "scope": "The bounded cohort's documentary continuity and identity checks, assuming the proposed signal occurs.",
    "provenance": {
      "refs": [
